func (s Student) Average() (float64, error) {
	if len(s.Scores) == 0 {
		return 0, ErrNoScores
	}
	total := 0
	for _, sc := range s.Scores {
		if sc < 0 || sc > 100 {
			return 0, fmt.Errorf("score %d: %v", sc, ErrBadScore)
		}
		total += sc
	}
	return float64(total) / float64(len(s.Scores)), nil
}
